percent_decode.kernel_code:
pub fn percent_decode(raw: &[u8], out: &mut [u8]) -> Option<usize> {
    if raw.len() > RAW_MAX {
        return None;
    }
    let mut i: usize = 0;
    let mut n: usize = 0;
    while i < raw.len() {
        let byte: u8;
        if raw[i] == PERCENT {
            // Need two more bytes after '%'.
            if raw.len() - i < 3 {
                return None;
            }
            let hi = hex_digit(raw[i + 1]);
            if hi < 0 {
                return None;
            }
            let lo = hex_digit(raw[i + 2]);
            if lo < 0 {
                return None;
            }
            byte = ((hi << 4) | lo) as u8;
            i += 3;
        } else {
            byte = raw[i];
            i += 1;
        }
        if n >= out.len() {
            return None;
        }
        out[n] = byte;
        n += 1;
    }
    Some(n)
}

