        return false;
    }
    if len > buf.len() {
        return false;
    }
    if is_dot_name(buf, len) {
        return false;
    }
    let mut i: usize = 0;
    while i < len {
        if is_separator(buf[i]) {
            return false;
        }
        i += 1;
    }
    true
}

